INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('nvmt_16_3', 'nvmt_16', 'Trực tiếp phụ trách một ca máy. Ngoài giờ đi ca, khi cần thiết phải có mặt ở buồng máy để kịp thời giải quyết công việc theo yêu cầu của thuyền trưởng hoặc đề nghị của máy phó.', 3);
