INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('m3_nvmt_q20', 'm3_nvmt', 'Máy trưởng là người giúp việc thuyền trưởng, trực tiếp phụ trách bộ phận máy và có trách nhiệm và quyền hạn sau đây:', NULL, 'm3_nvmt_q20_a4', 20);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('m3_nvmt_q20_a1', 'm3_nvmt_q20', 'Quản lý, nắm vững tình trạng kỹ thuật hệ thống động lực; tổ chức phân công, giám sát thuyên viên bộ phận máy trong quá trình vận hành.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('m3_nvmt_q20_a2', 'm3_nvmt_q20', 'Thực hiện đầy đủ quy định về vận hành máy móc, thiết bị; tổ chức bảo dưỡng thường xuyên, sửa chữa những hạng mục công việc được phép làm của máy móc, thiết bị để bảo đảm hệ thống máy hoạt động có hiệu quả.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('m3_nvmt_q20_a3', 'm3_nvmt_q20', 'Trực tiếp phụ trách một ca máy. Ngoài giờ đi ca, khi cần thiết phải có mặt ở buồng máy để kịp thời giải quyết công việc theo yêu cầu của thuyền trưởng hoặc đề nghị của máy phó.', 3);
