INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q83_a2', 'tt_antoan_q83', 'Do điều kiện làm việc phụ thuộc vào thời tiết, khí hậu, nắng nóng, mưa bão thất thường.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q83_a3', 'tt_antoan_q83', 'Do lỗi ẩn tì từ thiết bị máy móc.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q83_a4', 'tt_antoan_q83', 'Tất cả các nguyên nhân trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q84', 'tt_antoan', 'Để hạn chế những tai nạn có thể xảy ra yêu cầu mọi thuyền viên phải chấp hành những quy định sau:', NULL, 'tt_antoan_q84_a4', 4);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q84_a1', 'tt_antoan_q84', 'Gọn gàng, ngăn nắp, khoa học, tác phong công nghiệp.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q84_a2', 'tt_antoan_q84', 'Đối với tàu dầu nghiêm cấm đi giầy có đinh bằng kim loại trên boong.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q84_a3', 'tt_antoan_q84', 'Không kiểm tra và bảo dưỡng mặt boong nhất là lúc tàu đang hành trình và lúc trời tối, thời tiết xấu', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q84_a4', 'tt_antoan_q84', 'Tất cả các quy định trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q85', 'tt_antoan', 'Yêu cầu an toàn trong công việc làm dây:', NULL, 'tt_antoan_q85_a2', 5);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q85_a1', 'tt_antoan_q85', 'Khi ném dây và bắt dây mồi, người ném hoặc bắt dây phải đứng ở vị trí cao nhất trên tàu để quăng dây được xa.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q85_a2', 'tt_antoan_q85', 'Lúc làm dây phải chuẩn bị cuộn dây trước mặt, không đứng trong vòng dây.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q85_a3', 'tt_antoan_q85', 'Chuẩn bị tất cả các loại dây sẵn sàng trên mặt boong khi tàu ra, vào cầu cảng', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q85_a4', 'tt_antoan_q85', 'Thuỷ thủ đứng ở vị trí dễ quan sát chỉ huy công tác làm dây khi tàu cập cầu.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q86', 'tt_antoan', 'Yêu cầu ATLĐ khi làm việc trên cao ngoài mạn trên phương tiện đường thủy nội địa:', NULL, 'tt_antoan_q86_a4', 6);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q86_a1', 'tt_antoan_q86', 'Tất cả mọi trường hợp làm việc ngoài mạn tàu phải đứng trên ca bản.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q86_a2', 'tt_antoan_q86', 'Tuyệt đối nghiêm cấm làm việc trên cao ngoài mạn.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q86_a3', 'tt_antoan_q86', 'Khi tàu đang hành trình, làm việc ngoài mạn tàu cần phải có đầy đủ các trang thiết bị bảo hộ lao động.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q86_a4', 'tt_antoan_q86', 'd. Phải chuẩn bị đầy đủ các trang thiết bị ATLĐ như quần áo BHLĐ, thắt lưng, dây an toàn, phao.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q87', 'tt_antoan', 'Những thuyền viên được phân công làm nhiệm vụ đệm tàu phải chấp hành quy định sau:', NULL, 'tt_antoan_q87_a1', 7);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q87_a1', 'tt_antoan_q87', 'Người đệm phải đứng ở vị trí thích hợp, phải luôn tập trung vào công việc và đề phòng tàu va chạm chèn ép trượt ngã gây TNLĐ.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q87_a2', 'tt_antoan_q87', 'Quả đệm phải được làm bằng lốp cao su, có tính đàn hồi tốt; dây đeo phải đủ dài để khi đệm không phải cúi.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q87_a3', 'tt_antoan_q87', 'Người đệm phải đệm từ trên mũi tàu trước, phải luôn tập trung vào công việc và đề phòng tàu va chạm chèn ép trượt ngã gây TNLĐ.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q87_a4', 'tt_antoan_q87', 'Trong khi đệm phải quấn dây quả đệm vào tay đề phòng đệm rơi mất.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q88', 'tt_antoan', 'Để đảm bảo cho công việc cạo gỉ sơn được an toàn, mọi thuyền viên phải chấp hành những quy định sau:', NULL, 'tt_antoan_q88_a1', 8);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q88_a1', 'tt_antoan_q88', 'Khi sử dụng búa để gõ thì búa phải được nêm chặt vào cán. Phải thường xuyên kiểm tra đầu búa đề phòng búa tuột khỏi cán.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q88_a2', 'tt_antoan_q88', 'Không được cạo gỉ bằng búa máy. Nếu sử dụng thì phải kiểm tra độ cách điện, phải sử dụng găng tay điện và phải có dây tiếp mát.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q88_a3', 'tt_antoan_q88', 'Phải có dây an toàn khi gõ rỉ trên boong.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q88_a4', 'tt_antoan_q88', 'Tất cả các quy định trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q89', 'tt_antoan', 'Quy định an toàn khi sử dụng máy tời neo:', NULL, 'tt_antoan_q89_a4', 9);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q89_a1', 'tt_antoan_q89', 'Trước khi sử dụng phải kiểm tra các thiết bị an toàn như: Phanh, cóc hãm, nếu là máy tời điện thì phải kiểm tra an toàn điện, sau đó cho chạy thử thấy an toàn mới được sử dụng', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q89_a2', 'tt_antoan_q89', 'Trước khi cho máy chạy phải thông báo cho mọi người biết để đề phòng tai nạn. Khi máy đang hoạt động thì người điều khiển không được rời vị trí, khi ngừng máy thì phải cắt điện.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q89_a3', 'tt_antoan_q89', 'Đối với máy tời tay quay: Tay quay phải đúng quy cách, nếu tay quay bằng gỗ thì phải là gỗ tốt. Khi quay thì phải quay từ từ về phía trước, khi dây bắt đầu căng thì phải dừng để kiểm tra cóc hãm, phanh, nếu các cơ cấu đảm bảo an toàn thì mới quay tiếp.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q89_a4', 'tt_antoan_q89', 'Tất cả các quy định trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q90', 'tt_antoan', 'Đối với thuyền viên, thủy thủ khi mở hầm hàng cần phải chấp hành những quy định sau:', NULL, 'tt_antoan_q90_a2', 10);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q90_a1', 'tt_antoan_q90', 'Trước khi mở nắp hầm phải kiểm tra bên trên, dưới có người không rồi mới được mở.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q90_a2', 'tt_antoan_q90', 'Nắp hầm mở ra thì phải xếp gọn gàng, bằng phẳng kê sát hai bên miệng hầm hàng, không được xếp cao hơn miệng hầm hàng.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q90_a3', 'tt_antoan_q90', 'Miệng hầm hàng đã mở nếu ngừng làm việc thì tạm tời để yên chờ làm tiếp. Ban đêm phải có đèn báo hiệu.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q90_a4', 'tt_antoan_q90', 'Khi mở thì mở từ hai đầu về giữa, lúc đóng thì đóng từ giữa vào hai đầu.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q91', 'tt_antoan', 'Quy định về an toàn khi làm việc tại các cửa hầm và các két:', NULL, 'tt_antoan_q91_a1', 11);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q91_a1', 'tt_antoan_q91', 'Trước khi vào hầm phải có đủ ánh sáng, dùng thang thích hợp để trèo, trong hầm đi giày hoặc ủng an toàn', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q91_a2', 'tt_antoan_q91', 'Chỉ được vào két, hầm vào ban ngày.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q91_a3', 'tt_antoan_q91', 'Khi vào cần trang bị đầy đủ thiết bị thở, mặt nạ phòng độc nếu đã thông gió an toàn.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q91_a4', 'tt_antoan_q91', 'Không nhất thiết phải có thiết bị thử oxy trước khi vào.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q92', 'tt_antoan', 'Khi xếp dỡ hàng bao kiện phải chấp hành những quy định sau:', NULL, 'tt_antoan_q92_a4', 12);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q92_a1', 'tt_antoan_q92', 'Khi lấy hàng phải lấy từ dưới lên trên, từ thấp tới cao', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q92_a2', 'tt_antoan_q92', 'Trong một mã hàng thì xếp bao lành phía ngoài, bao rách phía trong.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q92_a3', 'tt_antoan_q92', 'Trong lúc làm việc cần đeo dây an toàn.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q92_a4', 'tt_antoan_q92', 'Những loại hàng như xi măng, hóa chất phải dùng ca bản, cấm dùng dây chão thắt ngang bao.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q93', 'tt_antoan', 'Các yếu tố cấu thành nên đám cháy là:', NULL, 'tt_antoan_q93_a1', 13);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q93_a1', 'tt_antoan_q93', 'Chất cháy, Oxi, nguồn nhiệt', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q93_a2', 'tt_antoan_q93', 'Chất cháy, khí Ni tơ, nguồn nhiệt.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q93_a3', 'tt_antoan_q93', 'Chất cháy, khí CO2, nguồn nhiệt.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q93_a4', 'tt_antoan_q93', 'Oxi, nguồn nhiệt, không khí.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q94', 'tt_antoan', 'Để chữa đám cháy do xăng dầu, ta dùng thiết bị chữa cháy sau:', NULL, 'tt_antoan_q94_a3', 14);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q94_a1', 'tt_antoan_q94', 'Bình bột khô ( Powder)', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q94_a2', 'tt_antoan_q94', 'Dùng nước', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q94_a3', 'tt_antoan_q94', 'Dùng bình bọt hoá học hoặc khí CO2.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q94_a4', 'tt_antoan_q94', 'Tất cả các thiết bị trên đều được.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q95', 'tt_antoan', 'Trong việc phân loại đám cháy thì đám cháy loại B là:', NULL, 'tt_antoan_q95_a2', 15);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q95_a1', 'tt_antoan_q95', 'Là cháy phát sinh từ chấy rắn dễ cháy như gỗ, bông, vải sợi...', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q95_a2', 'tt_antoan_q95', 'Là chất cháy sinh từ chấy lỏng như dầu mỡ, cồn, sơn, nhựa đường.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q95_a3', 'tt_antoan_q95', 'Là loại cháy do kim loại như Mg, bột nhôm, chất phim ảnh.....', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q95_a4', 'tt_antoan_q95', 'Là loại cháy do thiết bị điện chập mạch.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q96', 'tt_antoan', 'Các trang thiết bị cứu sinh được trang bị trên tàu bao gồm:', NULL, 'tt_antoan_q96_a4', 16);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q96_a1', 'tt_antoan_q96', 'Phao tròn cứu sinh, phao áo', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q96_a2', 'tt_antoan_q96', 'Bè cứu sinh thự thổi.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q96_a3', 'tt_antoan_q96', 'Dụng cụ nổi hay xuồng cứu sinh', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q96_a4', 'tt_antoan_q96', 'Tất cả các trang thiết bị trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q97', 'tt_antoan', 'Khi phát hiện có người rơi xuống nước, thuyền viên phải:', NULL, 'tt_antoan_q97_a4', 17);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q97_a1', 'tt_antoan_q97', 'Phải kịp thời ném nhiều phao cứu sinh cá nhân cho người bị nạn. Đồng thời thông báo cho người điều khiển tàu biết', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q97_a2', 'tt_antoan_q97', 'Phải dừng ngay máy và bẻ lái về phía người bị nạn để cho đuôi tàu tách xa ra và tránh cho người bị nạn không bị hút vào chân vịt', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q97_a3', 'tt_antoan_q97', 'Phải treo cờ báo hiệu hoặc phát tín hiệu “có người rơi xuống nước”', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q97_a4', 'tt_antoan_q97', 'Tất cả các hành động trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q98', 'tt_antoan', 'Các yếu tố gây ảnh hưởng tới môi trường từ hoạt động giao thông vận tải đường thuỷ nội địa bao gồm:', NULL, 'tt_antoan_q98_a4', 18);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q98_a1', 'tt_antoan_q98', 'Khí thải từ các phương tiện thủy', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q98_a2', 'tt_antoan_q98', 'Do dầu từ các hoạt động khai thác tàu thủy.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q98_a3', 'tt_antoan_q98', 'Chất thải rắn từ tàu.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q98_a4', 'tt_antoan_q98', 'Tất cả các yếu tố trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_antoan_q99', 'tt_antoan', 'Các yếu tố của môi trường ảnh hưởng đến sức khoẻ người lao động là:', NULL, 'tt_antoan_q99_a1', 19);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q99_a1', 'tt_antoan_q99', 'Không khí, bức xạ nhiệt, chất độc công nghiệp, nhiệt độ.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q99_a2', 'tt_antoan_q99', 'Nhiệt độ, không khí, bức xạ nhiệt.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_antoan_q99_a3', 'tt_antoan_q99', 'Không khí, bức xạ nhiệt, chất độc công nhiệp', 3);
