INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_vantai_q108', 'tt_vantai', 'Những chú ý khi vận chuyển hàng phân hóa học:', NULL, 'tt_vantai_q108_a4', 8);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q108_a1', 'tt_vantai_q108', 'Phương tiện chở phân hóa học phải khô, có đủ dụng cụ che đậy khi cần thiết.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q108_a2', 'tt_vantai_q108', 'Không xếp dỡ phân hóa học dưới trời mưa, khi xếp dỡ phải có công cụ mang hàng phù hợp.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q108_a3', 'tt_vantai_q108', 'Khi xếp hàng phân hóa học ở dưới tàu hay trong kho đều phải có đệm lót cách ly thành phương tiện và nền kho.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q108_a4', 'tt_vantai_q108', 'Tất cả các chú ý trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_vantai_q109', 'tt_vantai', 'Những việc cần phải làm khi vận chuyển hàng than là:', NULL, 'tt_vantai_q109_a4', 9);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q109_a1', 'tt_vantai_q109', 'Phải thường xuyên kiểm tra nhiệt độ hầm than, nếu nhiệt độ lên tới 40°C thì phải có biện pháp tản nhiệt.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q109_a2', 'tt_vantai_q109', 'Thường xuyên thông gió để thải khí độc, thải hỗn hợp khí than để tránh cháy nổ.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q109_a3', 'tt_vantai_q109', 'Với những chuyến đi dài ngày thì sau 5 ngày đầu phải tiến hành thông gió toàn bộ mặt ngoài, cứ 2 ngày thông gió một đợt, mỗi đợt 6h.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q109_a4', 'tt_vantai_q109', 'Tất cả các ý trên', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_vantai_q110', 'tt_vantai', 'Khi vận chuyển và bảo quản hàng lương thực tàu cần có điều kiện:', NULL, 'tt_vantai_q110_a4', 10);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q110_a1', 'tt_vantai_q110', 'Tàu vận chuyển hàng lương thực phải khô, sạch, không bị nhiễm bụi bẩn, có dụng cụ che đậy khi cần thiết.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q110_a2', 'tt_vantai_q110', 'Lương thực được đóng vào các bao (bao tải hoặc bao gai) trên đường đi phải thường xuyên kiểm tra nhiệt độ và độ ẩm.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q110_a3', 'tt_vantai_q110', 'Không xếp dỡ hàng khi trời mưa.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q110_a4', 'tt_vantai_q110', 'Tất cả các ý trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_vantai_q111', 'tt_vantai', 'Khi vận chuyển xi măng cần chú ý:', NULL, 'tt_vantai_q111_a1', 11);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q111_a1', 'tt_vantai_q111', 'Không xếp dỡ xi măng dưới trời mưa, nếu vận chuyển ở thể rời không xếp dỡ khi trời có gió to.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q111_a2', 'tt_vantai_q111', 'Phương tiện chở xi măng phải phun nước thường xuyên để tránh bụi bẩn.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q111_a3', 'tt_vantai_q111', 'Để xi măng ở gần hàng có tính bắt bụi, hàng đuờng, hàng mật lỏng và NH₃.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q111_a4', 'tt_vantai_q111', 'Tất cả các ý trên.', 4);
INSERT OR REPLACE INTO questions (id, subject_id, text, image, correct_answer_id, display_order) VALUES ('tt_vantai_q112', 'tt_vantai', 'Khi vận chuyển hàng quặng phải chú ý:', NULL, 'tt_vantai_q112_a4', 12);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q112_a1', 'tt_vantai_q112', 'Phải có đệm lót cách ly quặng với thành phương tiện.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q112_a2', 'tt_vantai_q112', 'Với quặng đồng phải thường xuyên kiểm tra nhiệt độ, hàm lượng nước, nếu có hiện tượng phát nhiệt thì phải đảo quặng.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q112_a3', 'tt_vantai_q112', 'Không xếp chung các loại quặng khác nhau vào cùng một khoang.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q112_a4', 'tt_vantai_q112', 'Tất cả các ý trên', 4);
