INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q113_a1', 'tt_vantai_q113', 'Yêu cầu được vận chuyển bằng đúng loại phương tiện, đúng giá trị loại vé, từ cảng, bến nơi đi đến cảng, bến nơi đến theo vé đã mua.', 1);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q113_a2', 'tt_vantai_q113', 'Được miễn cước phí hành lý mang theo với khối lượng theo quy định.', 2);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q113_a3', 'tt_vantai_q113', 'Yêu cầu bồi thường thiệt hại cho hành khách nếu không vận tải đến đúng địa điểm.', 3);
INSERT OR REPLACE INTO answers (id, question_id, text, display_order) VALUES ('tt_vantai_q113_a4', 'tt_vantai_q113', 'Tất cả các quyền nêu trên.', 4);
